Write-Output "=== Checking all imports resolve ==="; python -c "
import os
for root, dirs, files in os.walk('src'):
    for f in files:
        if f.endswith('.ts') or f.endswith('.tsx'):
            path = os.path.join(root, f)
            with open(path) as fp:
                content = fp.read()
            if 'from' in content:
                print(f'{path}: {len([l for l in content.split(chr(10)) if l.strip().startswith(\"import\") and \"from\" in l])} imports')
